Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class NativeApi { [DllImport("kernel32.dll")] public static extern uint GetTickCount(); }' -Language CSharp; $OperationResult = [NativeApi]::GetTickCount(); Get-ChildItem -Path $env:TEMP -Filter "*.tmp" | Select-Object -First 3
